gacM(){return"with places"},
gacL(){return"with heights"},
gacN(){return"with ways"},
gaIU(){return"Resume"},
gacJ(){return"Bring up to date"},
gaIi(){return"Delete area"},
aIZ(a){return"Save all of "+a+"?"},
